class TimeField(FieldBase):
    """
    Data from the `Time` field. This contains the value of the internal clock of the hardware.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     Hours
    1      1    u8     Minutes
    2      1    u8     Seconds
    3      1    u8     Frames
    4      1    bool   Current mode uses dropframes
    5      3    ?      padding
    ====== ==== ====== ===========

    After parsing:

    :ivar hours: Hours
    :ivar minutes: Minutes
    :ivar seconds: Seconds
    :ivar frames: Frames
    :ivar is_dropframe: Current mode uses dropframes
    """

    CODE = "Time"
    STRUCT = struct.Struct('>BBBB ?3x')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.hours = field[0]
        self.minutes = field[1]
        self.seconds = field[2]
        self.frames = field[3]
        self.is_dropframe = field[4]


    @classmethod
    def create(cls, hours: int = 0, minutes: int = 0, seconds: int = 0, frames: int = 0, is_dropframe: bool = False) -> Self:
        """
        :param hours: Hours, defaults to 0
        :param minutes: Minutes, defaults to 0
        :param seconds: Seconds, defaults to 0
        :param frames: Frames, defaults to 0
        :param is_dropframe: Current mode uses dropframes, defaults to False
        :return: Instance of TimeField with the data applied
        """
        raw = cls.STRUCT.pack(hours, minutes, seconds, frames, is_dropframe)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into TimeField.create()"""
        return self.hours, self.minutes, self.seconds, self.frames, self.is_dropframe

    def total_seconds(self):
        """get the time as amount of seconds (excluding the frames)"""
        return self.seconds + (60 * self.minutes) + (60 * 60 * self.hours)

    def __repr__(self):
        return f"<time {self.hours} {self.minutes} {self.seconds} {self.frames}>"


