class VideoModeCapabilityField(FieldBase):
    """
    Data from the `_VMC` field. This describes all the video modes supported by the hardware and the associated multiview
    and downconvert modes.

    The first 2 bytes is the number of modes supported, then there's a 13 byte block that's repeated for every mode that has
    the mode number, the possible multiview modes in this mode and the possible downconvert modes.

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      2    u16    Number of video modes
    ====== ==== ====== ===========

    Followed by this repeated block:

    ====== ==== ====== ===========
    Offset Size Type   Description
    ====== ==== ====== ===========
    0      1    u8     Video mode number referring to a VideoMode
    1      3    ?      padding
    4      4    u32    Multiview modes bitfield
    8      4    u32    Downscale modes bitfield
    12     1    bool   Requires reconfiguration
    ====== ==== ====== ===========

    After parsing:

    :ivar count: Number of video modes
    """

    CODE = "_VMC"
    STRUCT = struct.Struct('>H')
    REPEATED = struct.Struct('>B3x I I ?')

    def __init__(self, raw: bytes):
        """
        :param raw: Bytes containing the field contents
        """
        self.raw = raw
        field = self.STRUCT.unpack(raw)
        self.count = field[0]
        self.modes = []
        for i in range(self.count):
            rf = self.REPEATED.unpack_from(raw, self.STRUCT.size + (i * self.REPEATED.size))
            self.modes.append({
                "modenum": rf[0],
                "multiview": self._bitfield_to_modes(rf[1]),
                "downscale": self._bitfield_to_modes(rf[2]),
                "reconfig": rf[3],
                "mode": self._int_to_mode(rf[0]),
            })


    @classmethod
    def create(cls, count: int) -> Self:
        """
        :param count: Number of video modes
        :return: Instance of VideoModeCapabilityField with the data applied
        """
        raw = cls.STRUCT.pack(count)
        return cls(raw)

    def uncreate(self) -> tuple:
        """Create arguments to feed into VideoModeCapabilityField.create()"""
        return self.count,

    def _int_to_mode(self, mode: int):
        """The VideoMode corresponding with this mode"""
        return VideoModeField(VideoModeField.STRUCT.pack(mode))

    def _bitfield_to_modes(self, bitfield: int):
        """Convert a mode bitfield to a list of VideoModeField instances"""
        result = []
        for i in range(0, 32):
            if bitfield & (2 ** i):
                result.append(self._int_to_mode(i))
        return result

    def __repr__(self):
        return f"<video-mode-capability count={self.count}>"


